-- 세트 117: 인프라 장애 상황집: 연결이 안 될 때 층별로 좁히기 (이름, 포트, 시간, MTU)
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (117, 1, '장애 때 가장 먼저 치는 두 줄', '서비스에 연결이 안 된다는 신고가 왔습니다. ① **내 서버의 IP 주소**를 보고, ② **어떤 TCP 포트가 열려 있는지(LISTEN)** 확인하는 명령입니다. 빈칸을 채우세요.', '주소는 addr, 열린 포트는 tln(TCP·LISTEN·숫자) 조합이에요.', NULL, NULL, '[]', 'fill', '["addr", "tln", "route", "dns"]', NULL, '`ip addr` 은 이 서버가 가진 주소를, `ss -tln` 은 **듣고 있는(LISTEN) TCP 포트**를 보여 줍니다. 서비스가 "떠 있는지"는 프로세스가 아니라 그 포트가 열려 있는지로 확인하는 것이 확실해요.', '[0, 1]', 'ip {0}
ss -{1}', NULL, NULL),
  (117, 2, 'Could not resolve host', '`curl https://api.example.com` 이 `curl: (6) Could not resolve host: api.example.com` 로 실패합니다. 어느 단계의 문제일까요?', '"resolve"는 이름을 주소로 바꾸는 일이에요.', NULL, NULL, '[]', 'choice', '["서버의 디스크가 가득 찼다", "이름을 IP 주소로 바꾸는 단계(DNS, `/etc/hosts`, `resolv.conf`)의 문제이므로 이름 해석부터 확인한다", "서비스 포트가 닫혀 있다", "인증서가 만료됐다"]', 1, '연결(TCP)을 시도하기도 전에 실패한 것입니다. `/etc/resolv.conf` 의 nameserver, `/etc/hosts` 의 오타, 이름 철자를 먼저 보세요. 포트나 방화벽은 그다음 단계입니다.', NULL, NULL, NULL, NULL),
  (117, 3, 'refused 와 timed out 의 차이', '같은 서버의 8080 포트에 `curl` 을 쳤더니 한 번은 `Connection refused` 가 **즉시**, 다른 환경에서는 한참 멈췄다가 `Connection timed out` 이 났습니다. 알맞은 해석은 무엇일까요?', '"거절당함"과 "답이 없음"은 원인이 달라요.', NULL, NULL, '[]', 'choice', '["둘 다 서버가 꺼졌다는 같은 뜻이다", "refused 는 DNS 문제, timed out 은 디스크 문제다", "둘 다 비밀번호가 틀렸다는 뜻이다", "refused 는 서버에는 닿았지만 그 포트에서 듣는 서비스가 없다는 뜻이고, timed out 은 패킷이 중간에 버려지거나(방화벽, 보안 그룹) 경로가 막혔다는 뜻이다"]', 3, 'refused 는 상대 운영체제가 "그 포트에 아무도 없다"고 **바로 답한** 것입니다. timed out 은 아무 답이 없는 것이라 방화벽이 조용히 버리는 경우가 흔해요. 그래서 확인할 곳이 서비스 vs 방화벽·경로로 갈립니다.', NULL, NULL, NULL, NULL),
  (117, 4, '오류 코드별로 세어 보기', '`/tmp/net.log` 에 `curl` 오류 메시지가 쌓여 있습니다. 괄호 안의 **오류 코드(예: `(6)`)별로 몇 번씩** 나왔는지 세어 `/tmp/count.txt` 에 저장하세요. (`uniq -c` 결과 모양이면 됩니다)', '`grep -o` 로 `(숫자)` 만 뽑고 `sort | uniq -c` 로 세어요. 패턴은 `''([0-9]*)''`.
확인: `cat /tmp/net.log`', 'cat /tmp/net.log
grep -o ''([0-9]*)'' /tmp/net.log | sort | uniq -c > /tmp/count.txt
cat /tmp/count.txt

# (6) 이름 해석, (7) 연결 거절, (28) 시간 초과. 어느 코드가 많은지 보면 원인 층이 좁혀진다', '["sh", "-c", "rm -f /tmp/count.txt && printf ''%s\\\\n'' ''curl: (6) Could not resolve host: a.example.com'' ''curl: (7) Failed to connect to b.example.com port 443: Connection refused'' ''curl: (28) Connection timed out after 5001 milliseconds'' ''curl: (6) Could not resolve host: c.example.com'' > /tmp/net.log"]', '["sh", "-c", "( grep -qE ''^ *2 \\\\(6\\\\)$'' /tmp/count.txt ) && ( grep -qE ''^ *1 \\\\(7\\\\)$'' /tmp/count.txt ) && ( grep -qE ''^ *1 \\\\(28\\\\)$'' /tmp/count.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "(6) 이 2번이다", "cmd": ["sh", "-c", "grep -qE ''^ *2 \\\\(6\\\\)$'' /tmp/count.txt"]}, {"label": "(7) 이 1번이다", "cmd": ["sh", "-c", "grep -qE ''^ *1 \\\\(7\\\\)$'' /tmp/count.txt"]}, {"label": "(28) 이 1번이다", "cmd": ["sh", "-c", "grep -qE ''^ *1 \\\\(28\\\\)$'' /tmp/count.txt"]}]', '[{"title": "ss(8) 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}]'),
  (117, 5, '연결이 안 될 때 점검 순서', '서비스에 연결이 안 됩니다. 아래쪽 층(내 쪽)부터 위로 좁혀 가는 순서에 맞게 놓아 보세요.', '내 주소 → 이름 → 경로 → 포트 → 서비스 순서예요.', NULL, NULL, '[]', 'order', '["내 서버의 IP·경로가 정상인지 확인한다 (`ip addr`, `ip route`)", "이름이 주소로 바뀌는지 확인한다 (DNS, hosts)", "대상까지 가는 길이 열려 있는지 확인한다 (`ping`, `traceroute`)", "대상의 포트가 응답하는지 확인한다 (`nc -zv`, `curl`)", "서비스 로그와 설정을 확인한다"]', NULL, '아래 층이 막혀 있으면 위 층은 확인할 수 없습니다. ping 은 보안 정책으로 막혀 있는 경우도 많으니 ping 실패만으로 서버 다운이라 단정하지 말고 포트 확인까지 하세요.', '[0, 1, 2, 3, 4]', NULL, NULL, NULL),
  (117, 6, 'ss 출력에서 열린 포트만 뽑기', '`/tmp/ss.txt` 는 서버에서 `ss -ltn` 을 실행해 저장한 결과입니다. **듣고 있는 포트 번호만** 숫자 순서대로 한 줄에 하나씩 `/tmp/ports.txt` 에 저장하세요. (`8080` 은 목록에 없습니다)', '4번째 칸(`Local Address:Port`)의 마지막 `:` 뒤가 포트예요. `awk ''NR>1{n=split($4,a,":"); print a[n]}''` 에 `sort -n` 을 이어 보세요.
확인: `cat /tmp/ss.txt`', 'cat /tmp/ss.txt
awk ''NR>1{n=split($4,a,":"); print a[n]}'' /tmp/ss.txt | sort -n > /tmp/ports.txt
cat /tmp/ports.txt

# 서비스가 떠 있는지는 "그 포트가 LISTEN 인가"로 확인한다. 목록에 없으면 서비스가 안 떠 있는 것', '["sh", "-c", "rm -f /tmp/ports.txt && printf ''%s\\\\n'' ''State  Recv-Q Send-Q Local Address:Port Peer Address:Port'' ''LISTEN 0      128          0.0.0.0:22        0.0.0.0:*'' ''LISTEN 0      511          0.0.0.0:443       0.0.0.0:*'' ''LISTEN 0      511          0.0.0.0:80        0.0.0.0:*'' ''LISTEN 0      244        127.0.0.1:5432      0.0.0.0:*'' > /tmp/ss.txt"]', '["sh", "-c", "( [ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/ports.txt)\\" = \\"22 80 443 5432 \\" ] ) && ( ! grep -qx 8080 /tmp/ports.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ports.txt 가 22 80 443 5432 이다", "cmd": ["sh", "-c", "[ \\"$(tr \\"\\\\n\\" \\" \\" < /tmp/ports.txt)\\" = \\"22 80 443 5432 \\" ]"]}, {"label": "8080 이 없다", "cmd": ["sh", "-c", "! grep -qx 8080 /tmp/ports.txt"]}]', '[{"title": "ss(8) 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}]'),
  (117, 7, '처음에만 5초씩 느려요', '서버에서 외부 주소로 접속할 때 **매번 처음 5초 정도 멈췄다가** 이후에는 정상 속도입니다. `/etc/resolv.conf` 에는 nameserver 가 두 줄 있습니다. 가장 먼저 의심할 것은 무엇일까요?', '이름 해석은 첫 번째 nameserver 부터 차례로 물어봐요.', NULL, NULL, '[]', 'choice', '["첫 번째 nameserver 가 응답하지 않아 시간 초과 후 두 번째로 넘어가는 것이므로, 첫 번째 nameserver 의 상태와 순서를 확인한다", "디스크 입출력이 느리다", "이미지가 너무 크다", "서버 시간대가 다르다"]', 0, '응답 없는 nameserver 를 만나면 기본 대기(보통 약 5초) 뒤 다음 서버로 갑니다. 죽은 서버를 목록에서 빼거나 순서를 바꾸면 지연이 사라져요. 한 번 해석된 결과는 캐시되어 이후엔 빠릅니다.', NULL, NULL, NULL, NULL),
  (117, 8, '죽은 nameserver 빼고 파일 만들기', '`/tmp/resolv.conf` 의 첫 번째 nameserver `192.0.2.1` 이 응답하지 않습니다. 이 줄만 **뺀** 설정을 `/tmp/resolv.fixed` 에 만드세요. `search` 줄과 나머지 nameserver 는 그대로 있어야 합니다.', '`grep -v` 로 특정 줄만 빼고 출력할 수 있어요. 점(.)은 정규식에서 아무 글자라는 뜻이라 `-F` 를 붙이면 안전해요.
확인: `cat /tmp/resolv.conf`', 'cat /tmp/resolv.conf
grep -vF ''nameserver 192.0.2.1'' /tmp/resolv.conf > /tmp/resolv.fixed
cat /tmp/resolv.fixed

# 실제 /etc/resolv.conf 는 바꾸기 전에 반드시 백업한다. 여기서는 새 파일에 먼저 만들어 확인했다', '["sh", "-c", "rm -f /tmp/resolv.fixed && printf ''%s\\\\n'' ''search example.com'' ''nameserver 192.0.2.1'' ''nameserver 198.51.100.2'' > /tmp/resolv.conf"]', '["sh", "-c", "( ! grep -qF 192.0.2.1 /tmp/resolv.fixed ) && ( grep -qx \\"nameserver 198.51.100.2\\" /tmp/resolv.fixed ) && ( grep -qx \\"search example.com\\" /tmp/resolv.fixed )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "죽은 nameserver 가 없다", "cmd": ["sh", "-c", "! grep -qF 192.0.2.1 /tmp/resolv.fixed"]}, {"label": "두 번째 nameserver 가 있다", "cmd": ["sh", "-c", "grep -qx \\"nameserver 198.51.100.2\\" /tmp/resolv.fixed"]}, {"label": "search 줄이 남아 있다", "cmd": ["sh", "-c", "grep -qx \\"search example.com\\" /tmp/resolv.fixed"]}]', '[{"title": "ss(8) 매뉴얼", "url": "https://man7.org/linux/man-pages/man8/ss.8.html"}]'),
  (117, 9, '인증서는 멀쩡한데 만료됐대요', '`curl https://internal.example.com` 이 `certificate has expired or is not yet valid` 로 실패합니다. 인증서 파일의 유효기간은 내년까지이고 다른 서버에서는 정상입니다. 가장 먼저 확인할 것은 무엇일까요?', '유효한 기간인지 판단할 때 "지금 시각"을 기준으로 해요.', NULL, NULL, '[]', 'choice', '["레지스트리의 디스크 용량", "DNS 서버의 개수", "이 서버의 시스템 시간이 크게 틀어져 있는지 (`date`, 시간 동기화 상태)", "curl 의 버전 번호"]', 2, '인증서 검증은 서버 시계로 "지금이 유효기간 안인가"를 봅니다. 시계가 과거·미래로 틀어져 있으면 멀쩡한 인증서도 만료 또는 "아직 유효하지 않음"이 돼요. 다른 서버는 되고 한 서버만 안 될 때 특히 시간을 의심하세요.', NULL, NULL, NULL, NULL),
  (117, 10, '시간 동기화 상태 보기와 맞추기', 'chrony 를 쓰는 서버에서 ① 시계가 기준과 **얼마나 어긋났는지** 보고, ② 크게 어긋났을 때 **즉시 한 번에 맞추는** 명령입니다. 빈칸을 채우세요.', '상태를 추적해 보여 주는 서브명령, 그리고 한 걸음에 맞추는 서브명령이에요.', NULL, NULL, '[]', 'fill', '["tracking", "makestep", "stop", "erase"]', NULL, '`chronyc tracking` 은 현재 보정값(System time 의 어긋남)과 동기화 대상을 보여 줍니다. `chronyc makestep` 은 천천히 보정하지 않고 바로 시계를 맞춥니다. 시계가 갑자기 움직이면 로그 시간 순서나 만료 시간에 영향이 있을 수 있어 신중히 쓰세요.', '[0, 1]', 'chronyc {0}
chronyc {1}', NULL, NULL),
  (117, 11, '작은 요청은 되는데 큰 전송만 멈춰요', '`ping` 과 짧은 `curl` 은 잘 되는데, **큰 파일을 보내거나 응답이 클 때만** 연결이 멈추고 타임아웃이 납니다. 경로 중간에 터널(VPN)이 있습니다. 가장 의심되는 원인은 무엇일까요?', '한 번에 보낼 수 있는 패킷 크기에 한도가 있어요.', NULL, NULL, '[]', 'choice', '["서버의 사용자 계정이 많다", "경로 중간의 패킷 크기 한도(MTU)가 달라 큰 패킷이 버려지는 것이므로, 크기를 바꿔 가며 ping 해 한도를 찾는다", "디스크의 inode 가 부족하다", "DNS 캐시가 가득 찼다"]', 1, '작은 패킷은 통과하고 큰 패킷만 막히는 증상은 MTU/MSS 불일치의 전형입니다. `ping -M do -s 1472 대상` 처럼 "쪼개지 말라"는 옵션으로 크기를 줄여 가며 통과하는 최대 크기를 찾으세요. 터널은 헤더가 더해져 한도가 작아져요.', NULL, NULL, NULL, NULL);
